/* CrownOps private pilot. No live schedule, Gmail or QuickBooks connection is implied. */
'use strict';
const S={user:null,csrf:'',page:'dashboard',search:'',leadScope:'all',leadKind:'',leadStage:'',offset:0,taskScope:'active',scheduleView:'week',week:null,seq:0,modalContext:null};
const root=document.getElementById('root'), modal=document.getElementById('modal');
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>'CA$'+(Number(c||0)/100).toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2});
const compact=c=>'CA$'+Math.round(Number(c||0)/100).toLocaleString('en-CA');
const initials=n=>String(n||'CM').trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const demo=()=>Boolean(window.CROWNOPS_DEMO);
const symbols={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4z M16 3v4 M8 3v4 M4 11h16 M8 15h2 M14 15h2',spark:'m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8L12 3',mail:'M3 5h18v14H3z M3 5l9 7 9-7',wallet:'M3 5h17v15H3z M3 9h17 M15 13h6v4h-6z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',box:'m3 7 9-4 9 4v10l-9 4-9-4V7 M3 7l9 4 9-4 M12 11v10 M8 5l9 4',plug:'M8 3v5 M16 3v5 M5 8h14v3a7 7 0 0 1-7 7 M12 18v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',arrow:'M5 12h14 M14 7l5 5-5 5',check:'m5 12 4 4L20 5',close:'M6 6l12 12 M6 18 18 6',upload:'M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6',download:'M12 3v13 M7 11l5 5 5-5 M3 17v4h18v-4',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7',logout:'M9 4H3v16h6 M8 12h13 M16 7l5 5-5 5',truck:'M2 5h13v12H2z M15 10h4l3 4v3h-7 M7 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M21 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',phone:'M5 3H2v5c0 7 7 14 14 14h5v-5l-5-2-2 3c-4-1-7-4-8-8l3-2-2-5H5',menu:'M3 6h18 M3 12h18 M3 18h18',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3 M8 12l3 3 5-6',refresh:'M20 7v5h-5 M4 17v-5h5 M19 8a8 8 0 0 0-14-2 M5 16a8 8 0 0 0 14 2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${symbols[n]||symbols.file}"/></svg>`;
const crown=`<svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#f79c48" d="M5 34V15l10 9 9-16 9 16 10-9v19z M5 38h38v4H5z"/></svg>`;
const nav=[['dashboard','dashboard','Command center'],['sales','users','Sales & clients'],['quotes','spark','AI quote studio'],['schedule','calendar','Schedule'],['invoices','file','Final invoices'],['followups','mail','Inbox & follow-ups'],['payments','wallet','Payments'],['team','clock','Team & hours'],['inventory','box','Inventory'],['automations','plug','Automations'],['settings','settings','Settings & imports']];
const may=roles=>roles.includes(S.user?.role);
async function api(path,options={}){
 if(window.CROWNOPS_DEMO_API) return window.CROWNOPS_DEMO_API(path,options);
 const init={method:options.method||'GET',credentials:'same-origin',headers:{}};
 if(options.data!==undefined){init.headers['Content-Type']='application/json';init.body=JSON.stringify(options.data);}
 if(options.form)init.body=options.form;
 if(init.method!=='GET')init.headers['X-CSRF-Token']=S.csrf;
 const resp=await fetch('/api'+path,init);
 let body;try{body=await resp.json();}catch{body={detail:'Server returned an unreadable response.'};}
 if(!resp.ok){const error=new Error(typeof body.detail==='string'?body.detail:JSON.stringify(body.detail));error.status=resp.status;throw error;}
 return body;
}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),4200);}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function localDay(v){if(!v)return '';const d=new Date(v);return Number.isNaN(d.getTime())?String(v).slice(0,10):new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}
function dateLabel(v){if(!v)return 'Date to confirm';const d=new Date(String(v).slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?h(v):d.toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'});}
function timeLabel(v){return new Date(v).toLocaleTimeString('en-CA',{timeZone:'America/Toronto',hour:'numeric',minute:'2-digit'});}
function pill(value){const s=String(value||'Unknown');const color=/accepted|paid|approved|complete/i.test(s)?'teal':/quote|review|draft/i.test(s)?'purple':/new|moving|confirm/i.test(s)?'blue':/missing|pending|tentative|partial/i.test(s)?'orange':/lost|unpaid|error/i.test(s)?'red':'gray';return `<span class="pill ${color}">${h(s)}</span>`;}
function btn(action,text,cl='',attrs=''){return `<button class="${cl}" data-action="${action}" ${attrs}>${text}</button>`;}
function head(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('box')}<strong>${title}</strong><p>${text}</p>${action}</div>`;}
function field(name,label,value='',type='text',extra=''){return `<div class="form-field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}></div>`;}
function select(name,label,options,value='',extra=''){return `<div class="form-field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${extra}>${options.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${h(a[0])}" ${String(value)===String(a[0])?'selected':''}>${h(a[1])}</option>`;}).join('')}</select></div>`;}
function textArea(name,label,value='',rows=4){return `<div class="form-field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="${rows}">${h(value)}</textarea></div>`;}
function showModal(title,body,footer='',wide=false){modal.style.width=wide?'1060px':'850px';modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><div class="grow"></div>${btn('close',icon('close'),'btn-icon','aria-label="Close dialog"')}</div><div class="modal-body"><div class="modal-error" id="modal-error"></div>${body}</div>${footer?'<div class="modal-foot">'+footer+'</div>':''}`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function modalError(e){const box=document.getElementById('modal-error');if(box){box.textContent=e.message||String(e);box.scrollIntoView({block:'nearest'});}else toast(e.message||String(e));}
function readForm(form){return Object.fromEntries(new FormData(form));}
function checked(form,name){return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);}
function formFooter(form,label='Save',action=''){return `${btn('close','Cancel')}<button class="btn-primary" type="submit" form="${form}">${action?icon(action):''}${label}</button>`;}

function allowedPages(){const role=S.user.role;return role==='owner'?nav.map(n=>n[0]):role==='sales'?['dashboard','sales','quotes','communications','schedule','invoices','followups','inventory','automations']:role==='crew'?['schedule','invoices','team']:role==='accounting'?['schedule','invoices','payments','team','inventory']:['schedule','invoices','team','inventory'];}
function shell(){const role=S.user.role;const allowed=allowedPages();
 root.innerHTML=`<div class="app"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-icon">${crown}</div><div><strong>CrownOps</strong><small>CROWN MOVERS</small></div></div><div class="nav-label">WORKSPACE</div>${nav.filter(n=>allowed.includes(n[0])).map((n,i)=>`${i===6?'<div class="nav-label">OPERATIONS</div>':''}<button class="nav-button ${S.page===n[0]?'active':''}" data-page="${n[0]}">${icon(n[1])}<span>${n[2]}</span></button>`).join('')}<div class="sidebar-foot"><div class="workspace-label"><span class="dot"></span>${demo()?'Interactive design preview':'Private pilot workspace'}<div class="tiny" style="color:#91aacd;margin-top:4px">${demo()?'Fictional records. Nothing sent.':'Live schedule remains unchanged.'}</div></div><div class="profile"><div class="avatar">${h(initials(S.user.name))}</div><div><div style="color:white;font-size:12px;font-weight:600">${h(S.user.name)}</div><div style="font-size:10px">${h(role==='owner'?'Manager':role)} access</div></div>${btn('logout',icon('logout'),'logout','aria-label="Sign out"')}</div></div></aside><main class="main"><header class="topbar">${btn('menu',icon('menu'),'mobile-toggle btn-icon','aria-label="Open navigation"')}<div class="breadcrumb">Crown Movers ${icon('right')} <b id="crumb">Command center</b></div><div class="top-right">${may(['owner','sales'])?'<div class="searchbox">'+icon('search')+'<input id="global-search" placeholder="Find a client..." aria-label="Find a client"></div>':''}${demo()?'<label class="row small">Test as <select id="demo-role" aria-label="Test as role"><option value="owner" '+(role==='owner'?'selected':'')+'>Manager</option><option value="sales" '+(role==='sales'?'selected':'')+'>Sales agent</option><option value="crew" '+(role==='crew'?'selected':'')+'>Mover</option></select></label>':''}<span class="date-label">Montr&eacute;al time &middot; ET</span><div class="avatar">${h(initials(S.user.name))}</div></div></header><div class="pilot-strip" id="pilot-strip">${icon('shield')}<span>${demo()?'Interactive preview with fictional sample data. Changes reset when reloaded. No AI, email or payment calls are made.':'Private review build v5.0. Test only; Carl\'s live schedule, Gmail, accounting and payments are not synchronized.'}</span></div><section class="content" id="content"></section></main></div>`;
 const gs=document.getElementById('global-search');if(gs)gs.addEventListener('keydown',e=>{if(e.key==='Enter'){S.search=gs.value;S.offset=0;navigate('sales');}});
}
async function navigate(page){if(!allowedPages().includes(page)){toast('This section is restricted to your role.');page='schedule';}S.page=page;if(!document.getElementById('content'))shell();document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('sidebar').classList.remove('open');const n=nav.find(n=>n[0]===page);document.getElementById('crumb').textContent=n?n[2]:'Workspace';const seq=++S.seq;document.getElementById('content').innerHTML='<div class="startup">Loading your workspace...</div>';
 try{const renderers={dashboard:dashboard,sales:sales,quotes:quotesPage,schedule:schedulePage,invoices:invoicesPage,followups:followups,payments:paymentsPage,team:teamPage,inventory:inventoryPage,automations:automationsPage,settings:settingsPage};const html=await renderers[page]();if(seq!==S.seq)return;document.getElementById('content').innerHTML=html;bindPage();}catch(e){if(e.status===401)return loginScreen();document.getElementById('content').innerHTML=empty('This section could not load',h(e.message),btn('refresh','Try again'));}}
async function dashboard(){const [s,l,q]=await Promise.all([api('/stats'),api('/leads?kind=Form&limit=5'),api('/quotes')]);const metrics=[['Client inquiries',s.leads,demo()?'Fictional sample inquiries':'Imported records + new inquiries','users',''],['Active opportunities',s.active_leads,'Selected for current sales work','spark','teal'],['Follow-ups due',s.tasks_due,'Active tasks; historical imports excluded','phone','orange'],['Jobs in pilot',s.jobs,'Separate from your live calendar','calendar','purple']];const counts=['New Lead','Contacted','Quote Sent','Accepted','Booked'].map(x=>l.items.filter(r=>r.stage===x).length);return head('Command center','Your sales and operations, in one workspace.',btn('new-lead',icon('plus')+'New inquiry','btn-primary')+btn('import',icon('upload')+'Import workbook'))+`<div class="metric-grid">${metrics.map(m=>`<div class="panel metric"><div class="label"><span>${m[0]}</span><span class="ico ${m[4]}">${icon(m[3])}</span></div><div class="value">${Number(m[1]||0).toLocaleString()}</div><div class="foot">${m[2]}</div></div>`).join('')}</div><div class="split"><div class="panel"><div class="panel-head"><h2>Recent moving inquiries</h2>${btn('go-sales','View sales '+icon('arrow'),'btn-text tiny')}</div>${leadTable(l.items,false)}<div class="table-footer"><span>Source records preserved. Availability is not inferred.</span><span>${s.unassigned} unassigned</span></div></div><div class="panel"><div class="panel-head"><h2>Next actions</h2><span class="pill orange">Review first</span></div><div class="panel-body"><div class="task-row"><div class="ico">${icon('users')}</div><div class="grow"><div class="task-title">Claim and qualify inquiries</div><span class="tiny muted">Keep the historical import out of live follow-ups.</span></div>${btn('go-sales',icon('right'),'btn-text')}</div><div class="task-row">${icon('file')}<div class="grow"><div class="task-title">Review your pricing snapshot</div><span class="tiny muted">Resolve minimums and fuel rules explicitly.</span></div>${btn('go-settings',icon('right'),'btn-text')}</div><div class="task-row">${icon('calendar')}<div class="grow"><div class="task-title">Connect Carl's actual schedule</div><span class="tiny muted">Source code and live data are still required.</span></div>${btn('go-schedule',icon('right'),'btn-text')}</div><div class="spacer"></div><div class="callout teal"><strong>${s.quotes} saved quote revision${s.quotes===1?'':'s'}</strong>Approved pricing + reviewed scope. AI helps prepare the facts; the calculator handles the numbers.</div></div></div></div><div class="spacer"></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>What happens next</h2><span class="eyebrow">YOUR WORKFLOW</span></div><div class="panel-body"><div class="row wrap"><span class="pill blue">Inquiry</span>${icon('right')}<span class="pill purple">Estimate</span>${icon('right')}<span class="pill orange">Acceptance + deposit</span>${icon('right')}<span class="pill teal">Dispatch</span></div><p class="small muted" style="margin-top:16px">The client record follows the job. No repeated entry, no automatic booking promises, and no emails sent without review.</p></div></div><div class="panel"><div class="panel-head"><h2>Workbook import</h2>${pill(s.latest_import?'Snapshot loaded':'Not imported')}</div><div class="panel-body"><p class="small muted">${s.latest_import?'Your sales records, calls, follow-ups, team, stock and seasonal rates are available in this private database. Derived payroll rows are not treated as transactions.':'Import your original CrownOps v8 workbook to bring your sales records into the test workspace.'}</p>${btn('go-settings','Review import &amp; setup '+icon('arrow'),'btn-text')}</div></div></div>`;}
function leadTable(items,actions=true){if(!items.length)return empty('No inquiries in this view','Add a new inquiry, change the filters, or import the CrownOps workbook.',btn('new-lead','Add inquiry','btn-primary'));return `<div class="table-wrap"><table><thead><tr><th>Client / source</th><th>Move</th><th>Stage</th><th>Readiness</th>${actions?'<th>Owner</th>':''}<th></th></tr></thead><tbody>${items.map(l=>`<tr><td><div class="row"><div class="avatar">${h(initials(l.client_name))}</div><div><div class="client-name">${h(l.client_name)}</div><div class="client-sub">${h(l.source)} &middot; ${h(l.lead_type)}</div></div></div></td><td><div>${dateLabel(l.move_date)}</div><div class="client-sub">${h(l.home_size||'Details needed')}</div></td><td>${pill(l.stage)}${l.archived_import?'<div class="client-sub">Imported snapshot</div>':''}</td><td>${l.missing?.length?`<span class="pill orange">${l.missing.length} details needed</span>`:'<span class="pill teal">Ready to review</span>'}</td>${actions?`<td><span class="tiny muted">${h(l.assigned_to?(l.assigned_to===S.user.id?'You':l.assigned_to):'Unassigned')}</span></td>`:''}<td>${btn('open-lead',icon('right'),'btn-text',`data-id="${h(l.id)}" aria-label="Open ${h(l.client_name)}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
async function sales(){const p=new URLSearchParams({q:S.search,stage:S.leadStage,kind:S.leadKind,scope:S.leadScope,offset:S.offset,limit:30});const l=await api('/leads?'+p);return head('Sales & clients','One place for each inquiry, every detail, and the next conversation.',btn('new-lead',icon('plus')+'New inquiry','btn-primary'))+`<div class="filterbar"><div class="searchbox">${icon('search')}<input id="sales-search" placeholder="Search name, phone or address" value="${h(S.search)}" aria-label="Search inquiries"></div><select id="lead-scope" class="input-inline" aria-label="Inquiry scope">${[['all','All inquiries'],['active','Active opportunities'],['imported','Imported history'],['mine','My inquiries']].map(x=>`<option value="${x[0]}" ${x[0]===S.leadScope?'selected':''}>${x[1]}</option>`).join('')}</select><select id="lead-kind" class="input-inline" aria-label="Inquiry type">${[['','All inquiry types'],['Form','Website forms'],['Missed Call','Missed calls'],['Voicemail','Voicemails']].map(x=>`<option value="${x[0]}" ${x[0]===S.leadKind?'selected':''}>${x[1]}</option>`).join('')}</select><div class="grow"></div><span class="tiny muted">${l.total.toLocaleString()} records</span></div><div class="panel">${leadTable(l.items)}<div class="table-footer"><span>Showing ${l.items.length?S.offset+1:0}&ndash;${S.offset+l.items.length} of ${l.total}</span><div class="row">${btn('page-prev',icon('left'),'btn-small',S.offset===0?'disabled':'')}${btn('page-next',icon('right'),'btn-small',S.offset+l.items.length>=l.total?'disabled':'')}</div></div></div><p class="source-warning">Imported records are historical snapshots, not evidence of unhandled current inquiries. Claim and review a record before contacting a client.</p>`;}
async function openLead(id){const l=await api('/leads/'+encodeURIComponent(id));S.modalContext={lead:l};const ops=may(['owner','sales']);const vals=[['Pickup',l.pickup],['Destination',l.dropoff],['Pickup access',l.pickup_access],['Destination access',l.dropoff_access],['Pickup walk',l.pickup_walk],['Destination walk',l.dropoff_walk],['Box count',l.boxes],['Preferred date',dateLabel(l.move_date)]];showModal(h(l.client_name),`<div class="row wrap"><span class="pill blue">${h(l.source)}</span>${pill(l.stage)}${l.archived_import?'<span class="source-tag">Imported &middot; notifications suppressed</span>':''}<div class="grow"></div>${ops?btn('edit-lead','Edit details','btn-small',`data-id="${h(id)}"`):''}</div><div class="spacer"></div><div class="row wrap">${l.phone?`<a class="row small" href="tel:${h(l.phone.replace(/[^+\d]/g,''))}">${icon('phone')}${h(l.phone)}</a>`:''}${l.email?`<a class="row small" href="mailto:${h(l.email)}">${icon('mail')}${h(l.email)}</a>`:''}</div><div class="spacer"></div><div class="grid2"><div class="stack"><div class="panel"><div class="panel-head"><h3>Move details</h3>${pill(l.home_size||'Size unknown')}</div><div class="panel-body info-grid">${vals.map(x=>`<div><div class="info-label">${x[0]}</div><div class="info-value">${h(x[1]||'Not provided')}</div></div>`).join('')}</div></div><div><h3>Inventory &amp; access notes</h3><div class="message-draft">${h([l.inventory,l.heavy_items,l.notes].filter(Boolean).join('\n\n')||'No inventory supplied yet.')}</div></div></div><div class="stack"><div class="callout ${l.missing.length?'orange':'teal'}"><strong>${l.missing.length?'Details to confirm':'Ready for a human review'}</strong>${h(l.missing.join(', ')||'Review the inventory, access, route and truck capacity before approval.')}</div>${ops?`<div class="row wrap">${!l.assigned_to?btn('claim','Claim inquiry','btn-soft',`data-id="${h(id)}"`):''}${l.archived_import?btn('activate','Move to active sales','btn-small',`data-id="${h(id)}"`):''}</div><div class="grid2">${btn('new-quote',icon('file')+'Build estimate','btn-primary',`data-id="${h(id)}"`)}${btn('ai-compose',icon('spark')+'AI assistant','',`data-id="${h(id)}"`)}</div>`:''}<div><h3>Saved estimates</h3>${l.quotes.length?l.quotes.map(q=>`<div class="task-row"><div class="grow"><div class="small strong">Revision ${q.revision} &middot; ${compact(q.result.low_cents)} &ndash; ${compact(q.result.high_cents)}</div><div class="tiny muted">${q.result.movers} movers &middot; ${q.result.trucks} truck(s) &middot; before tax</div></div>${pill(q.status)}${btn('open-quote',icon('right'),'btn-text',`data-id="${h(q.id)}"`)}</div>`).join(''):'<p class="tiny muted">No saved estimates yet.</p>'}</div><div><h3>Client timeline</h3>${l.messages.length?l.messages.slice(0,4).map(m=>`<div class="activity-row"><span class="activity-dot"></span><div><div class="tiny strong">${h(m.kind)}</div><div class="tiny muted">${h(m.body.slice(0,160))}</div></div></div>`).join(''):'<p class="tiny muted">Email accounts are not synchronized. Record a note or paste a received message.</p>'}</div>${ops?`<form id="note-form" data-form="note"><input type="hidden" name="lead_id" value="${h(id)}">${select('kind','Add to timeline',['Note','Incoming pasted email','Draft reply','External communication recorded'])}${textArea('body','Message or note','',3)}<div class="spacer"></div><button class="btn-small" type="submit">Save note</button></form>`:''}</div></div>`,btn('close','Close'),true);}
async function editLead(id=''){const l=id?await api('/leads/'+encodeURIComponent(id)):{};S.modalContext={lead:l};showModal(id?'Edit client details':'New client inquiry',`<form id="lead-form" data-form="lead"><input type="hidden" name="id" value="${h(id)}"><input type="hidden" name="version" value="${l.version||''}"><div class="grid2">${field('client_name','Client name',l.client_name,'text','required')}${field('move_date','Requested move date',l.move_date,'date')}${field('email','Email',l.email,'email')}${field('phone','Phone',l.phone)}${field('pickup','Pickup address',l.pickup)}${field('dropoff','Destination address',l.dropoff)}${field('home_size','Move size',l.home_size)}${field('boxes','Box count / range',l.boxes)}${field('pickup_access','Pickup floors / stairs / elevator',l.pickup_access)}${field('dropoff_access','Destination floors / stairs / elevator',l.dropoff_access)}${field('pickup_walk','Pickup walk / parking',l.pickup_walk)}${field('dropoff_walk','Destination walk / parking',l.dropoff_walk)}${select('language','Client language',['English','French','Unknown'],l.language||'English')}${select('stage','Sales stage',[...new Set(['New Lead','Contacted','Waiting for details','Quote Sent','Accepted','Booked','Closed','Lost','Commercial Review',l.stage].filter(Boolean))],l.stage||'New Lead')}${field('source','Source',l.source||'Manual')}${select('priority','Priority',['Normal','High'],l.priority||'Normal')}${textArea('inventory','Furniture, boxes and other inventory',l.inventory||'')}${textArea('heavy_items','Special handling / heavy items',l.heavy_items||'',2)}${textArea('notes','Internal notes',l.notes||'',2)}</div></form>`,formFooter('lead-form',id?'Save changes':'Create inquiry'),true);}
async function quotesPage(){const quotes=await api('/quotes');return head('AI quote studio','Extract the details. Calculate from your rates. Review before sending.',btn('choose-ai',icon('spark')+'Analyze a client message','btn-soft')+btn('choose-quote',icon('plus')+'New estimate','btn-primary'))+`<div class="grid3"><div class="panel connector-card"><div class="row">${icon('mail')}<span class="integration-name">1. Understand the request</span></div><p>Paste a client email. AI suggests structured details and the questions still worth asking.</p><span class="pill gray">AI connection required</span></div><div class="panel connector-card"><div class="row">${icon('file')}<span class="integration-name">2. Build the estimate</span></div><p>Reviewed crew and duration. Seasonal rates, explicit minimum, transport, fuel and materials.</p><span class="pill blue">Deterministic calculation</span></div><div class="panel connector-card"><div class="row">${icon('shield')}<span class="integration-name">3. Approve the next step</span></div><p>Saved versions, human approval and a draft email. Client acceptance is separate from dispatch.</p><span class="pill teal">No automatic sending</span></div></div><div class="spacer"></div><div class="panel"><div class="panel-head"><h2>Estimates &amp; revisions</h2><span class="tiny muted">All amounts before applicable taxes</span></div>${quotes.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Version</th><th>Crew / trucks</th><th>Service time</th><th>Estimate range</th><th>Status</th><th></th></tr></thead><tbody>${quotes.map(q=>`<tr><td class="client-name">${h(q.client_name)}</td><td>Revision ${q.revision}</td><td>${q.result.movers} movers / ${q.result.trucks} truck(s)</td><td>${q.result.service_low}&ndash;${q.result.service_high} h</td><td class="amount strong">${compact(q.result.low_cents)} &ndash; ${compact(q.result.high_cents)}</td><td>${pill(q.status)}</td><td>${btn('open-quote',icon('right'),'btn-text',`data-id="${h(q.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your estimates will live here','Choose a client, set the reviewed service scope and calculate an internal draft.',btn('choose-quote','Build an estimate','btn-primary'))}</div>`;}
async function chooseLead(action){const l=await api('/leads?kind=Form&limit=100');showModal(action==='ai'?'Choose a client for AI assistance':'Choose a client for an estimate',`<p class="muted small">Select a client to keep the details, draft and estimate linked.</p><form id="choose-form" data-form="choose"><input type="hidden" name="action" value="${action}">${select('lead_id','Client',l.items.map(x=>[x.id,x.client_name+' | '+(x.move_date||'Date needed')]))}</form>`,formFooter('choose-form','Continue'));}
function quoteSummary(r){if(!r)return '<div class="quote-summary"><div class="eyebrow">INTERNAL ESTIMATE</div><div class="quote-price">Ready when you are</div><p class="small muted">Choose your pricing settings and reviewed service hours, then calculate.</p></div>';return `<div class="quote-summary"><div class="eyebrow">ESTIMATED RANGE &middot; CAD</div><div class="quote-price">${compact(r.low_cents)} &ndash; ${compact(r.high_cents)}</div><div class="tiny muted">Before applicable taxes &middot; not a booking</div><div class="spacer"></div><div class="quote-line"><span>Service &middot; ${r.service_low}&ndash;${r.service_high} h</span><b>${compact(r.service_low_cents)}&ndash;${compact(r.service_high_cents)}</b></div><div class="quote-line"><span>Base transport &middot; ${r.transport_hours} h</span><b>${money(r.transport_cents)}</b></div><div class="quote-line"><span>Fuel &middot; ${r.trucks} truck(s)</span><b>${money(r.fuel_cents)}</b></div><div class="quote-line"><span>Materials / other</span><b>${money(r.materials_cents+r.other_cents)}</b></div><div class="quote-line"><span>Discount</span><b>${money(r.discount_cents)}</b></div><div class="spacer"></div><div class="tiny muted">${r.movers} movers at ${money(r.hourly_rate_cents)}/h<br>Minimum: ${r.minimum_hours} service hours</div></div>`;}
async function newQuote(lid){const [l,prices]=await Promise.all([api('/leads/'+encodeURIComponent(lid)),api('/pricing')]);if(!prices.length){toast('Import your workbook and review the rate snapshot first.');return navigate('settings');}const p=prices.find(x=>x.approved)||prices[0];S.modalContext={lead:l,prices,lastResult:null};showModal('Build an estimate',`<div class="row"><div class="avatar">${h(initials(l.client_name))}</div><div><div class="strong">${h(l.client_name)}</div><div class="tiny muted">${h(l.pickup||'Pickup needed')} &rarr; ${h(l.dropoff||'Destination needed')}</div></div><div class="grow"></div><span class="pill purple">Draft</span></div><div class="spacer"></div><div class="quote-layout"><form id="quote-form" data-form="quote"><input type="hidden" name="lead_id" value="${h(lid)}"><input type="hidden" name="lead_version" value="${l.version}"><div class="grid2">${select('pricing_id','Rate snapshot',prices.map(x=>[x.id,x.label+(x.approved?' | approved':' | pending approval')]),p.id)}${field('move_date','Requested move date',l.move_date,'date','required')}${select('movers','Reviewed team size',[2,3,4,5,6].map(x=>[x,x+' movers']),3)}${select('trucks','Moving / fuel-charge trucks',[1,2,3,4].map(x=>[x,x+' truck(s)']),1)}${field('hours_low','Base service hours: low','','number','step="0.25" min="0.25" max="80" required')}${field('hours_high','Base service hours: high','','number','step="0.25" min="0.25" max="100" required')}${select('allowance_percent','Planning allowance (apply once)',[[0,'None: range already planned'],[20,'20% on base service hours'],[25,'25% on base service hours']],20)}${field('transport_hours','Separate base transport hours',1,'number','step="0.25" min="0" required')}${select('minimum_key','Select the applicable minimum',[['','Choose a source setting'],...['morning_service_minimum','afternoon_micro_minimum','minimum_billable_hours'].filter(k=>p.settings[k]!==undefined).map(k=>[k,k.replaceAll('_',' ')+' | '+p.settings[k]+' h'])],'','required')}${select('fuel_key','Select the fuel rule',[['','Choose a source setting'],...['normal_local_fuel','extended_local_fuel','gas_per_truck'].filter(k=>p.settings[k]!==undefined).map(k=>[k,k.replaceAll('_',' ')+' | '+money(p.settings[k]*100)])],'','required')}${field('materials_amount','Materials allowance (CAD)',0,'number','step="0.01" min="0"')}${field('other_amount','Other agreed charges (CAD)',0,'number','step="0.01" min="0"')}${field('discount_amount','Approved discount amount (CAD)',0,'number','step="0.01" min="0"')}${field('deposit_required','Required deposit (confirm policy)',300,'number','step="0.01" min="0"')}${textArea('internal_note','Review assumptions / special instructions','',2)}</div><div class="spacer"></div><div class="callout">Service hours include travel between client stops. The separate transport field is for base travel only. Long-distance jobs require a separately reviewed quote outside this pilot calculator.</div></form><div><div id="quote-result">${quoteSummary(null)}</div><div class="spacer"></div><div class="callout orange"><strong>${l.missing.length?'Missing information':'Human scope review required'}</strong>${h(l.missing.join(', ')||'Check the actual inventory, access, route, timing and truck capacity before approval.')}</div><p class="source-warning">${h(p.label)}. This calculator does not inspect truck capacity, route restrictions or actual availability.</p></div></div>`,`${btn('calculate-quote',icon('refresh')+'Calculate','btn-soft')}<button class="btn-primary" type="submit" form="quote-form">Save draft revision</button>`,true);}
async function openQuote(qid){const [qs,conn]=await Promise.all([api('/quotes'),qboState()]);const q=qs.find(x=>x.id===qid);if(!q)throw Error('Quote not found.');S.modalContext={quote:q,qbo:conn};const owners=may(['owner','dispatch']);const qboButton=qboReady(conn)&&['Approved','Accepted'].includes(q.status)&&may(['owner','sales'])?btn('qbo-estimate','Sync to '+qboLabel(conn),'btn-soft',`data-id="${h(qid)}"`):'';showModal('Estimate revision '+q.revision,`<div class="row"><h3>${h(q.client_name)}</h3><div class="grow"></div>${pill(q.status)}</div><div class="spacer"></div><div class="quote-layout"><div>${quoteSummary(q.result)}<p class="source-warning">${h(q.result.tax_note)}</p></div><div class="stack"><div class="callout"><strong>Versioned estimate</strong>Accepted rates and inputs are saved with this revision. Later edits do not rewrite it.</div><div class="info-grid"><div><div class="info-label">Requested date</div>${dateLabel(q.inputs.move_date)}</div><div><div class="info-label">Deposit requirement</div>${money(Number(q.inputs.deposit_required??300)*100)}</div></div>${q.status==='Draft'&&owners?`<form id="approve-quote-form" data-form="approve-quote"><input type="hidden" name="id" value="${h(qid)}">${textArea('note','Inventory / access / routing review note','',3)}<div class="spacer"></div><label class="checkbox-label"><input name="reviewed" type="checkbox" required>I have reviewed the actual scope, route, capacity and timing. No booking or email is sent by approving.</label><div class="spacer"></div><button class="btn-primary" type="submit">Approve estimate</button></form>`:''}${q.status==='Approved'?`<form id="accept-quote-form" data-form="accept-quote"><input type="hidden" name="id" value="${h(qid)}">${field('reference','Client acceptance evidence / email reference','','text','required')}<div class="spacer"></div><button type="submit" class="btn-soft">Record client acceptance</button></form>`:''}${q.status==='Accepted'?'<div class="callout teal"><strong>Client acceptance recorded</strong>Dispatch must still verify the deposit and resource availability before confirming the job.</div>':''}${qboButton}${btn('quote-text',icon('mail')+'Prepare email text','',`data-id="${h(qid)}"`)}${q.status!=='Draft'?`<a href="/api/quotes/${h(qid)}/email" class="row small" ${demo()?'data-action="demo-export"':''}>${icon('download')}Download unsent email (.eml)</a>`:''}${q.status==='Accepted'&&may(['owner','dispatch'])?btn('new-job',icon('calendar')+'Plan job','btn-primary',`data-quote="${h(qid)}" data-lead="${h(q.lead_id)}"`):''}</div></div>`,btn('close','Close'),true);}
async function aiCompose(lid){const [l,c]=await Promise.all([api('/leads/'+encodeURIComponent(lid)),api('/integrations')]);S.modalContext={lead:l,aiResult:null};showModal('AI client assistant',`<div class="row"><span class="ai-orb">${icon('spark')}</span><div><h3>${h(l.client_name)}</h3><div class="tiny muted">Extract details and draft a reply. Never send or confirm automatically.</div></div><div class="grow"></div>${pill(c.ai_configured?'Configured; call required':'Not connected')}</div><div class="spacer"></div><div class="grid2"><form id="ai-form" data-form="ai"><input type="hidden" name="lead_id" value="${h(lid)}">${select('language','Reply language',['English','French'],l.language==='French'?'French':'English')}${textArea('text','Paste the client email or request',l.inventory||'',11)}<div class="spacer"></div><label class="checkbox-label"><input type="checkbox" name="consent_to_process" required>I am authorized to process this selected client message and relevant move details with the configured AI provider.</label><div class="spacer"></div><button class="btn-primary" type="submit">${icon('spark')}Analyze &amp; draft</button><p class="source-warning">${demo()?'Preview only: sample output, no real AI request or tokens.':c.ai_configured?'API calls use tokens. Input and output usage are recorded on the server.':'Set OPENAI_API_KEY and OPENAI_MODEL on the server to enable this. No credentials are stored in the browser.'}</p></form><div id="ai-output"><div class="callout"><strong>Your assistant, not an autopilot</strong>Suggested fields must be reviewed. Calculated prices come from the approved rate table and your reviewed service hours.</div><div class="spacer"></div><div class="message-draft muted">The suggested summary, questions and reply will appear here.</div></div></div>`,btn('close','Close'),true);}
function weekDays(){if(!S.week){const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-d.getDay());S.week=d;}return Array.from({length:7},(_,i)=>{const d=new Date(S.week);d.setDate(d.getDate()+i);return d;});}
function dateIso(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
async function schedulePage(){
 const [jobs, imported]=await Promise.all([api('/jobs'), api('/schedule-imports/events')]);
 S.importedSchedule=imported;
 const all=[...jobs.map(j=>({id:j.id,date:localDay(j.start_at),time:timeLabel(j.start_at),title:j.title,phase:j.phase,status:j.status,crew:j.crew_names.join(' + '),truck:j.truck_names.join(', '),imported:false})),
 ...imported.filter(j=>!j.promoted_job_id).map(j=>({id:j.id,date:j.date,time:j.time_label,title:j.client_name,phase:j.service,status:'Imported - review',crew:j.crew_raw,truck:j.truck_label,imported:true}))].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
 const days=weekDays(), ids=days.map(dateIso), wk=all.filter(j=>ids.includes(j.date));
 const card=j=>`<button class="job-card" data-action="${j.imported?'open-imported-job':'open-job'}" data-id="${h(j.id)}"><div class="status">${h(j.time)} &middot; ${h(j.status)}</div><strong>${h(j.title)}</strong><div>${pill(j.phase)}</div><small>${h(j.crew||'Crew needs review')}</small><span class="tiny strong">${h(j.truck||'Truck needs review')}</span></button>`;
 return head('Schedule','Working jobs and imported Crown Schedule records.',may(['owner','sales','dispatch'])?btn('new-job',icon('plus')+'New job','btn-primary'):'')+
 `<div class="callout orange"><strong>${imported.length} original schedule entries imported for review</strong>Source comments and client details are preserved. These are not new confirmations. Unknown times, repeated deposits and conflicting addresses require review before invoicing or dispatch.</div><div class="spacer"></div>
 <div class="calendar-tools"><div class="row">${btn('week-prev',icon('left'),'btn-icon')}${btn('week-today','Today')}${btn('week-next',icon('right'),'btn-icon')}<span class="date-range">${dateLabel(ids[0])} &ndash; ${dateLabel(ids[6])}</span><input type="date" id="calendar-jump" aria-label="Jump to schedule date" value="${ids[0]}" style="max-width:150px"></div><div class="segmented">${btn('view-week','Week',S.scheduleView==='week'?'selected':'')}${btn('view-list','All imported dates',S.scheduleView==='list'?'selected':'')}</div></div>
 ${S.scheduleView==='week'?`<div class="panel calendar-scroll"><div class="week-grid">${days.map(d=>`<div class="day-col"><div class="day-head"><small>${d.toLocaleDateString('en-CA',{weekday:'short'})}</small><b>${d.getDate()}</b></div><div class="day-jobs">${wk.filter(j=>j.date===dateIso(d)).map(card).join('')}</div></div>`).join('')}</div></div>`:
 `<div class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Client / phase</th><th>Time</th><th>Crew / truck</th><th>Status</th><th></th></tr></thead><tbody>${all.map(j=>`<tr><td>${h(j.date)}</td><td><strong>${h(j.title)}</strong><br>${h(j.phase)}</td><td>${h(j.time)}</td><td>${h(j.crew)}<br>${h(j.truck)}</td><td>${pill(j.status)}</td><td>${btn(j.imported?'open-imported-job':'open-job','Open','btn-small',`data-id="${h(j.id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`}
 <p class="source-warning">Calendar navigation supports 2027. Empty dates do not prove staff or truck availability. The uploaded source has no dated client bookings in 2027.</p>`;
}
async function openImportedJob(id){
 const j=(S.importedSchedule||await api('/schedule-imports/events')).find(x=>x.id===id);if(!j)throw Error('Imported record not found.');
 const summary=j.linked_document?.text_summary||'';
 showModal(h(j.client_name),`<div class="callout orange"><strong>Source record, not a new booking confirmation</strong>${h(j.review_note||'Confirm crew, truck, times, scope and payment evidence before activating.')}</div><div class="spacer"></div>
 <div class="info-grid">${[['Date / service',j.date+' / '+j.service],['Start',j.time_label],['Contact',j.phone+' / '+j.email],['Source status',j.source_status],['Pickup as entered',j.pickup_raw],['Stops as entered',j.dropoffs_raw.map(x=>x.address).join(' / ')],['Crew as entered',j.crew_raw],['Truck header',j.truck_label],['Quoted hours',j.quoted_hours_raw],['Actual hours',j.actual_hours_raw]].map(x=>`<div><div class="info-label">${h(x[0])}</div><div class="info-value">${h(x[1]||'Not supplied')}</div></div>`).join('')}</div>
 <h3>Original notes</h3><div class="message-draft">${h(j.notes_raw)}\n\n${h(j.comments.map(c=>c.cell+': '+c.text).join('\n\n'))}</div>
 ${summary?`<h3>Linked document text summary</h3><div class="message-draft">${h(summary)}</div><p class="tiny muted">Images were not imported. Original link is retained below.</p>`:''}
 <h3>Review flags</h3><div class="message-draft">${h(j.flags.join('\n'))}</div>
 <h3>Original references</h3><p class="tiny muted">${h(j.source_ref)}</p>${j.links.filter(l=>/^https:\/\//.test(l.url)).map(l=>`<p><a target="_blank" rel="noopener noreferrer" href="${h(l.url)}">${h(l.cell)} - original reference</a></p>`).join('')}
 <details><summary>Preserved source cell values</summary><div class="message-draft">${h(JSON.stringify(j.raw_cells,null,2))}</div></details>`,btn('close','Close'),true);
}
async function newJob(data={}){const [leads,employees,vehicles,quotes]=await Promise.all([api('/client-projects').then(items=>({items})),api('/employees'),api('/vehicles'),api('/quotes')]);S.modalContext={leads:leads.items,employees,vehicles,quotes};const q=quotes.find(x=>x.id===data.quote);const day=data.date||q?.inputs.move_date||today();const leadid=data.lead||q?.lead_id||leads.items[0]?.id||'';const available=vehicles.filter(v=>v.active);showModal('Plan a job',`<div class="callout orange"><strong>This does not change Carl's live schedule</strong>For a confirmed job, verify acceptance, deposit, crew, drivers, trucks and access. Imported fleet records need activation in Settings first.</div><div class="spacer"></div><form id="job-form" data-form="job"><div class="grid2">${select('lead_id','Client',leads.items.map(l=>[l.id,l.client_name+' | '+(l.move_date||'Date needed')]),leadid,'required')}${select('quote_id','Accepted estimate',[['','Manual planning / no linked quote'],...quotes.filter(q=>q.status==='Accepted').map(q=>[q.id,q.client_name+' | revision '+q.revision])],q?.id||'')}${field('title','Job title',q?.client_name||'')}${select('phase','Service phase',['Moving','Packing','Delivery','Junk removal','Long distance','Storage'])}${field('start_at','Crew block begins (local ET)',day+'T09:00','datetime-local','required')}${field('end_at','Crew block ends (include buffers)',day+'T17:00','datetime-local','required')}${select('status','Booking state',['Tentative','Confirmed'],q?'Confirmed':'Tentative')}<div></div><div class="form-field"><label>Movers / drivers</label><div class="check-list">${employees.filter(e=>e.active).map(e=>`<label><input type="checkbox" name="crew_ids" value="${h(e.id)}"><span>${h(e.name)}${e.driver_verified?'<span class="muted"> &middot; driver</span>':''}</span></label>`).join('')||'<span class="muted tiny">Import the employee directory first.</span>'}</div></div><div class="form-field"><label>Verified available trucks</label><div class="check-list">${available.map(v=>`<label><input type="checkbox" name="truck_ids" value="${h(v.id)}">${h(v.name)}</label>`).join('')||'<span class="muted tiny">Activate actual trucks in Settings before assigning.</span>'}</div></div>${textArea('stops','Ordered stops (one full address per line)','',3)}${textArea('notes','Crew instructions and arrival window','',3)}${textArea('exception_reason','Owner exception reason, only when needed','',2)}<label class="checkbox-label full"><input type="checkbox" name="capacity_reviewed">I reviewed load capacity, authorized drivers, access and the complete blocked time, including travel. A visible time slot is not proof the work can fit.</label></div></form>`,formFooter('job-form','Save job'),true);}
async function openJob(jid){const jobs=await api('/jobs');const j=jobs.find(x=>x.id===jid);if(!j)throw Error('Job not found.');S.modalContext={job:j};showModal(h(j.title),`<div class="row">${pill(j.phase)}${pill(j.status)}<div class="grow"></div><span class="tiny muted">Working job</span></div><div class="spacer"></div><div class="info-grid"><div><div class="info-label">Crew block</div>${dateLabel(localDay(j.start_at))}<br>${timeLabel(j.start_at)} &ndash; ${timeLabel(j.end_at)}</div><div><div class="info-label">Assigned team</div>${h(j.crew_names.join(', '))}<div class="tiny muted">${h(j.truck_names.join(', '))}</div></div><div><div class="info-label">Pickup</div>${h(j.client.pickup)}<div class="tiny muted">${h(j.client.pickup_access)}</div></div><div><div class="info-label">Destination</div>${h(j.client.dropoff)}<div class="tiny muted">${h(j.client.dropoff_access)}</div></div><div><div class="info-label">Contact</div><a href="tel:${h(j.client.phone.replace(/[^+\d]/g,''))}">${h(j.client.phone)}</a></div><div><div class="info-label">Additional stops</div>${j.stops.map(h).join('<br>')||'None recorded'}</div></div><div class="spacer"></div><h3>Inventory &amp; job notes</h3><div class="message-draft">${h([j.client.inventory,j.client.heavy_items,j.notes].filter(Boolean).join('\n\n')||'No notes recorded.')}</div><div class="spacer"></div><div class="row wrap">${['Confirmed','In progress','Completed'].includes(j.status)?btn('job-invoice','Final invoice','btn-soft',`data-id="${h(jid)}"`):''}${j.status==='Confirmed'?btn('job-status','Start job','btn-primary',`data-id="${h(jid)}" data-version="${j.version}" data-status="In progress"`):''}${j.status==='In progress'?btn('job-status','Mark completed','btn-primary',`data-id="${h(jid)}" data-version="${j.version}" data-status="Completed"`):''}${j.status==='Tentative'&&may(['owner','sales','dispatch'])?btn('confirm-job','Review &amp; confirm','btn-primary',`data-id="${h(jid)}"`):''}${['In progress','Completed'].includes(j.status)&&may(['owner','dispatch','crew'])?btn('add-time','Record actual hours','btn-soft',`data-id="${h(jid)}"`):''}${may(['owner','dispatch'])&&!['Completed','Cancelled'].includes(j.status)?btn('cancel-job','Cancel job','btn-danger',`data-id="${h(jid)}" data-version="${j.version}"`):''}</div>`,btn('close','Close'));}
async function followups(){const tasks=await api('/tasks?scope='+S.taskScope);return head('Inbox & follow-ups','A clear next action for every conversation. No automatic sending.',btn('go-sales','Open client records','btn-soft'))+`<div class="filterbar"><div class="segmented">${btn('tasks-active','Current work',S.taskScope==='active'?'selected':'')}${btn('tasks-imported','Imported backlog',S.taskScope==='imported'?'selected':'')}</div><div class="grow"></div><span class="tiny muted">Showing up to 200 tasks</span></div><div class="panel">${tasks.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Action</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><div class="client-name">${h(t.client_name||'Unmatched historical record')}</div><div class="client-sub">${h(t.phone||'')}</div></td><td>${h(t.title)}${t.historical?'<div class="tiny muted">Imported; no outbound automation</div>':''}</td><td>${dateLabel(t.due_date)}</td><td>${pill(t.status)}</td><td><div class="row">${t.lead_id?btn('open-lead','Open','btn-small',`data-id="${h(t.lead_id)}"`):''}${t.status!=='Done'&&may(['owner','sales','dispatch'])?btn('complete-task',icon('check'),'btn-small',`data-id="${h(t.id)}" aria-label="Mark done"`):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No current follow-up tasks','New inquiries create an internal review task. Imported historical tasks stay in the separate backlog.')}</div><div class="spacer"></div><div class="callout"><strong>Email delivery is controlled in Connections</strong>Draft replies and received messages stay on the client timeline. Configure and test the account in Connections; a call link or downloaded email does not mean it was sent.</div>`;}
async function paymentsPage(){const [p,conn]=await Promise.all([api('/payments'),qboState()]);const verified=p.filter(x=>x.verified).reduce((a,x)=>a+x.amount_cents,0);const pending=p.filter(x=>!x.verified).reduce((a,x)=>a+x.amount_cents,0);const qbo=qboReady(conn)&&may(['owner','accounting']);return head('Payments','Track receipts and deposits without confusing them with invoices.',may(['owner','sales','accounting','dispatch'])?btn('new-payment',icon('plus')+'Record payment','btn-primary'):'')+`<div class="grid2"><div class="panel metric"><div class="label">Verified receipts, net of reversals</div><div class="value">${money(verified)}</div><div class="foot">Manual verification in this pilot. Not a bank connection.</div></div><div class="panel metric"><div class="label">Awaiting verification</div><div class="value">${money(pending)}</div><div class="foot">These amounts do not satisfy a verified-deposit booking gate.</div></div></div><div class="spacer"></div><div class="panel">${p.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Purpose / method</th><th>Amount</th><th>Reference</th><th>Status</th><th></th></tr></thead><tbody>${p.map(x=>`<tr><td class="client-name">${h(x.client_name)}</td><td>${h(x.purpose)}<div class="tiny muted">${h(x.method)}</div></td><td class="strong amount">${money(x.amount_cents)}</td><td class="truncate">${h(x.reference)}</td><td>${pill(x.reverses_id?'Reversal':x.verified?'Verified':'Pending')}</td><td><div class="row">${!x.verified&&!x.reverses_id&&may(['owner','accounting'])?btn('verify-payment','Verify','btn-small',`data-id="${h(x.id)}"`):''}${!x.reverses_id&&x.amount_cents>0&&may(['owner','accounting'])?btn('reverse-payment','Reverse','btn-small',`data-id="${h(x.id)}"`):''}${qbo&&x.verified&&!x.reverses_id&&x.amount_cents>0?btn('qbo-payment','Sync QBO','btn-small',`data-id="${h(x.id)}"`):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No payment entries yet','Record a received payment with its reference, then verify it. This screen does not charge cards or transfer money.')}</div><p class="source-warning">Deposits credit the final balance; they are not additional revenue. Correct entries with a reversal, never by deleting the original record.</p>`;}
async function newPayment(){const l={items:await api('/client-projects')};showModal('Record a received payment',`<form id="payment-form" data-form="payment"><div class="grid2">${select('lead_id','Client',l.items.map(x=>[x.id,x.client_name]),'','required')}${field('amount','Amount (CAD)','','number','min="0.01" step="0.01" required')}${select('purpose','Purpose',['Deposit','Final payment'])}${select('method','Method',['Interac','Credit card','Cash','Cheque','Other'])}${field('reference','Receipt / payment reference','','text','required')}${may(['owner','accounting'])?'<label class="checkbox-label"><input type="checkbox" name="verified">I have verified receipt of these funds.</label>':''}</div><div class="spacer"></div><p class="tiny muted">Recording a payment does not initiate a payment, send a receipt or post to QuickBooks.</p></form>`,formFooter('payment-form','Record payment'));}
async function teamPage(){const e=await api('/employees');const times=may(['owner','accounting','dispatch','crew'])?await api('/times'):[];return head('Team & hours','Employee records, assignments, and actual time awaiting review.',may(['owner'])?btn('invite',icon('plus')+'Invite team member','btn-primary'):'')+`<div class="panel"><div class="panel-head"><h2>${S.user.role==='crew'?'Your employee record':'Employee directory'}</h2><span class="tiny muted">Imported employees are not automatically login accounts</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Driver authorization</th>${may(['owner','accounting'])?'<th>Source hourly rate</th>':''}<th>Status</th><th></th></tr></thead><tbody>${e.map(x=>`<tr><td class="client-name">${h(x.name)}</td><td>${h(x.role)}</td><td>${pill(x.driver_verified?'Verified':'Not verified')}</td>${may(['owner','accounting'])?`<td>${money(x.hourly_cents)}/h</td>`:''}<td>${pill(x.active?'Active':'Inactive')}</td><td>${may(['owner'])?btn('driver-review','Review driver','btn-small',`data-id="${h(x.id)}"`):''}</td></tr>`).join('')}</tbody></table></div>${!e.length?empty('No employees imported','Load the employee directory from your workbook.'):''}</div><div class="spacer"></div><div class="panel"><div class="panel-head"><h2>Actual time submissions</h2><span class="pill gray">Not payroll processing</span></div>${times.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Job</th><th>Service</th><th>Transport</th><th>Status</th><th></th></tr></thead><tbody>${times.map(t=>`<tr><td class="client-name">${h(t.employee_name)}</td><td>${h(t.job_title)}</td><td>${(t.service_minutes/60).toFixed(2)} h</td><td>${(t.transport_minutes/60).toFixed(2)} h</td><td>${pill(t.status)}</td><td>${t.status!=='Approved'&&may(['owner','accounting'])?btn('approve-time','Approve','btn-small',`data-id="${h(t.id)}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No submitted hours','Open an in-progress or completed job to record actual employee hours. Incomplete workbook payroll examples are excluded.')}</div><p class="source-warning">Quoted hours, customer-billable hours, and employee hours are separate. Taxes, overtime, vacation and actual payroll processing are not calculated by this pilot.</p>`;}
async function inviteForm(){const e=await api('/employees');showModal('Invite a team member',`<form id="invite-form" data-form="invite"><div class="grid2">${field('name','Name','','text','required')}${field('email','Email','','email','required')}${select('role','Access role',[['sales','Sales'],['dispatch','Dispatch'],['crew','Crew'],['accounting','Accounting'],['owner','Manager (full access)']],'crew')}${select('employee_id','Link employee record',[['','No linked employee'],...e.map(x=>[x.id,x.name])])}</div><div class="spacer"></div><p class="small muted">Creates a private, one-use invitation link valid for 48 hours. No invitation email is sent automatically. A crew login needs a linked employee to see its assigned jobs.</p></form>`,formFooter('invite-form','Create invitation'));}
async function addTime(jid){const [jobs,employees]=await Promise.all([api('/jobs'),api('/employees')]);const j=jobs.find(x=>x.id===jid);showModal('Record actual employee hours',`<form id="time-form" data-form="time"><input type="hidden" name="job_id" value="${h(jid)}"><p class="strong">${h(j.title)}</p><div class="grid2">${select('employee_id','Assigned employee',employees.filter(x=>j.crew_ids.includes(x.id)).map(x=>[x.id,x.name]))}${field('service_hours','Actual service hours','','number','step="0.25" min="0" max="24" required')}${field('transport_hours','Actual paid transport hours',0,'number','step="0.25" min="0" max="24"')}${textArea('note','Time notes','',2)}</div><div class="spacer"></div><div class="callout">This is a time submission for review, not an automatic payroll payment. Record actual hours, not the customer estimate.</div></form>`,formFooter('time-form','Submit time'));}
async function inventoryPage(){const items=await api('/inventory');return head('Inventory','Track supplies coming in, going out, and returning from jobs.')+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Quantity</th><th>Minimum</th><th>Source selling price</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td class="client-name">${h(x.name)}</td><td>${h(x.category)}</td><td class="strong">${x.quantity}</td><td>${x.minimum}</td><td>${money(x.sell_cents)}</td><td>${pill(x.quantity<=x.minimum?'Reorder':'In stock')}</td><td>${may(['owner','dispatch'])?btn('stock-move','Log movement','btn-small',`data-id="${h(x.id)}" data-name="${h(x.name)}"`):''}</td></tr>`).join('')}</tbody></table></div>${!items.length?empty('No stock imported','Import the workbook to load the source inventory snapshot.'):''}</div><p class="source-warning">Opening quantities and prices come from the uploaded workbook. Confirm physical counts and current selling prices before use.</p>`;}
async function automationsPage(){const a=await api('/integrations');const used=a.ai_runs.reduce((n,r)=>n+r.input_tokens+r.output_tokens,0);const cards=[['spark','AI assistant',a.ai_configured?'Configured; not live-tested':'Not configured','Selected message extraction and EN/FR draft replies. No automatic quote approval.'],['mail','Gmail','Not connected','Manual drafts and client timeline are available. OAuth/integration still required.'],['file','QuickBooks','Export queue only','Approved estimates can be exported as payloads. Nothing has been posted.'],['plug','Website / n8n intake',a.intake_configured?'Signed endpoint configured':'Not configured','HMAC-signed intake endpoint with duplicate protection and internal review tasks.'],['calendar','Carl\'s live schedule','Not connected','Source project and live data/API handoff required. This schedule is isolated.'],['wallet','Payments','Manual verification','No bank sync, card processing or automatic charges in this build.']];return head('Automations & AI usage','Know what is connected, what ran, and what still needs a person.')+`<div class="grid3">${cards.map(c=>`<div class="panel connector-card"><div class="row">${icon(c[0])}<span class="integration-name">${c[1]}</span></div><p>${c[3]}</p>${pill(c[2])}</div>`).join('')}</div><div class="spacer"></div><div class="grid2"><div class="panel"><div class="panel-head"><h2>AI token usage</h2><span class="tiny muted">${h(a.ai_model)}</span></div><div class="panel-body"><div class="row"><div><div class="eyebrow">RECORDED COMPLETED CALLS</div><div style="font-size:29px;font-weight:650;margin-top:7px">${used.toLocaleString()} <span class="small muted">tokens</span></div></div><div class="grow"></div><span class="pill blue">Monthly cap ${a.ai_monthly_token_limit.toLocaleString()}</span></div><p class="tiny muted" style="margin-top:12px">Input, cached input and output usage are recorded per request. Unresolved calls retain a conservative reservation against the token budget. No dollar-cost estimate is invented.</p></div></div><div class="panel"><div class="panel-head"><h2>Accounting export queue</h2><span class="pill orange">Unsent</span></div><div class="panel-body">${a.events.length?a.events.slice(0,5).map(e=>`<div class="task-row"><div class="grow"><div class="tiny strong">${h(e.event_type)}</div><div class="tiny muted">${h(e.object_id)}</div></div><a href="/api/integrations/outbox/${h(e.id)}" ${demo()?'data-action="demo-export"':''}>Export JSON</a></div>`).join(''):'<p class="small muted">An internally approved quote creates one draft-export request. No QuickBooks write or client email happens automatically.</p>'}</div></div></div><div class="spacer"></div><div class="panel"><div class="panel-head"><h2>Workflow notes from your workbook</h2><span class="tiny muted">Source labels, not verified live status</span></div>${a.source_controls.length?`<div class="table-wrap"><table><thead><tr><th>Workflow</th><th>Workbook status</th><th>Next action recorded in source</th></tr></thead><tbody>${a.source_controls.map(x=>`<tr><td>${h(x.Automation)}</td><td>${pill(x['Live Status'])}</td><td>${h(x['Next Action'])}</td></tr>`).join('')}</tbody></table></div>`:empty('No source controls loaded','Import the workbook to preserve its workflow registry.')}</div>`;}
async function settingsPage(){const owner=may(['owner']);const [imports,p,vehicles,users]=await Promise.all([may(['owner','accounting'])?api('/imports'):Promise.resolve([]),api('/pricing'),api('/vehicles'),api('/users')]);S.settingsData={prices:p,vehicles,users};return head('Settings & imports','Your source data, rates and access controls. All changes are traceable.',owner?btn('import',icon('upload')+'Import CrownOps workbook','btn-primary'):'')+`<div class="grid2"><div class="panel"><div class="panel-head"><h2>Workbook migration</h2><span class="pill blue">Snapshot import</span></div><div class="panel-body">${imports.length?imports.slice(0,2).map(x=>`<div><div class="small strong">${h(x.filename)}</div><p class="tiny muted">${h(x.created_at.slice(0,10))} &middot; Source preserved; no live overwrites</p><div class="row wrap">${Object.entries(x.report.counts).filter(([k,v])=>['Leads','Calls','Follow-Ups','Employees'].includes(k)).map(([k,v])=>`<span class="pill gray">${v} ${h(k)}</span>`).join('')}</div><div class="spacer"></div><div class="callout orange"><strong>${x.report.quarantined.length} schedule row(s) quarantined</strong>Incomplete schedule examples and derived payroll results are not treated as valid operational transactions.</div></div>`).join('<hr class="divider">'):'<p class="small muted">Import the supplied .xlsx here. Leads, calls, follow-ups, employees, stock and rates will be loaded into this separate database.</p>'}</div></div><div class="panel"><div class="panel-head"><h2>Team access</h2>${owner?btn('invite','Invite','btn-small'):''}</div><div class="panel-body">${users.map(u=>`<div class="task-row"><div class="avatar">${h(initials(u.name))}</div><div class="grow"><div class="tiny strong">${h(u.name)}</div><div class="tiny muted">${h(u.email)}</div></div>${pill(u.active?u.role:'Inactive')}${owner&&u.id!==S.user.id&&u.active?btn('disable-user',icon('close'),'btn-text',`data-id="${h(u.id)}" aria-label="Revoke access"`):''}</div>`).join('')}</div></div></div><div class="spacer"></div><div class="panel"><div class="panel-head"><h2>Seasonal rate snapshots</h2><span class="tiny muted">Customer crew rates, not employee wages</span></div>${p.length?p.map((pv,i)=>`<div class="panel-body"><div class="row"><div class="grow"><div class="strong small">${h(pv.label)}</div><div class="tiny muted">${h(pv.id)} &middot; explicit fuel and minimum selections required</div></div>${pill(pv.approved?'Approved':'Needs approval')}${!pv.approved&&owner?btn('approve-pricing','Review &amp; approve','btn-small',`data-id="${h(pv.id)}"`):''}</div>${i===0?`<div class="table-wrap" style="margin-top:15px"><table><thead><tr><th>Season</th><th>2 movers</th><th>3 movers</th><th>4 movers</th><th>5 movers</th><th>6 movers</th></tr></thead><tbody>${pv.rates.map(r=>`<tr><td>${h(r['Season / Date Range'])}</td>${[2,3,4,5,6].map(c=>`<td>${money(r[c+' movers']*100)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</div>`).join(''):empty('No pricing snapshot yet','Import the workbook before generating estimates.')}</div><div class="spacer"></div><div class="panel"><div class="panel-head"><h2>Fleet verification</h2>${owner?btn('new-vehicle','Add truck','btn-small'):''}</div><div class="panel-body">${vehicles.map(v=>`<div class="task-row">${icon('truck')}<div class="grow"><div class="strong small">${h(v.name)}</div><div class="tiny muted">${h(v.notes)}</div></div>${pill(v.active?'Active':'Not verified')}${!v.active&&may(['owner','dispatch'])?btn('activate-vehicle','Verify','btn-small',`data-id="${h(v.id)}"`):''}</div>`).join('')||'<p class="small muted">Import and verify actual vehicle records before dispatch.</p>'}</div></div><div class="spacer"></div>${may(['owner','dispatch','accounting'])?btn('history',icon('clock')+'View change history'):''}`;}
function bindPage(){const search=document.getElementById('sales-search');if(search)search.addEventListener('keydown',e=>{if(e.key==='Enter'){S.search=e.target.value;S.offset=0;navigate('sales');}});for(const [id,key]of[['lead-scope','leadScope'],['lead-kind','leadKind']]){const el=document.getElementById(id);if(el)el.addEventListener('change',()=>{S[key]=el.value;S.offset=0;navigate('sales');});}}
function quoteData(){const f=document.getElementById('quote-form');if(!f.reportValidity())return null;const d=readForm(f);for(const k of ['lead_version','movers','trucks','hours_low','hours_high','allowance_percent','transport_hours','materials_amount','other_amount','discount_amount','deposit_required'])d[k]=Number(d[k]);return d;}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied. Nothing was sent.');}catch{showModal('Copy this text',textArea('copy','Select and copy',text,14),btn('close','Close'));}}
async function qboState(){try{return await api('/connections');}catch{return null;}}
function qboReady(state){return Boolean(state?.quickbooks?.authorized_at&&state.quickbooks?.mappings_complete&&state.quickbooks?.writes_enabled);}
function qboLabel(state){return state?.quickbooks?.environment==='production'?'QuickBooks':'QuickBooks sandbox';}
function noteAction(title,action,id,description,extra={}){S.modalContext={...S.modalContext,noteAction:{action,id,extra,version:S.modalContext.job?.version}};showModal(title,`<p class="small muted">${description}</p><form id="action-form" data-form="action-note">${textArea('note','Review note / reason','',4)}<label class="checkbox-label"><input type="checkbox" name="acknowledge" required>I have reviewed this action and want to proceed in the pilot.</label></form>`,formFooter('action-form','Confirm'))}

// One delegated handler works for dynamically rendered screens and dialogs.
document.addEventListener('click',async e=>{
 const page=e.target.closest('[data-page]');if(page){e.preventDefault();return navigate(page.dataset.page);}
 const el=e.target.closest('[data-action]');if(!el)return;
 e.preventDefault();const a=el.dataset.action,id=el.dataset.id;
 try{
  if(['open-invoice','job-invoice','issue-invoice','correct-invoice','download-invoice','invoice-deposit'].includes(a))return await invoiceClick(a,id);
  if(a==='close')return modal.close();
  if(a==='menu')return document.getElementById('sidebar').classList.toggle('open');
  if(a==='refresh')return navigate(S.page);
  if(a==='logout'){if(!demo())await api('/logout',{method:'POST'});S.user=null;return loginScreen();}
  if(a.startsWith('go-'))return navigate(a.slice(3));
  if(a==='new-lead')return editLead();
  if(a==='edit-lead')return editLead(id);
  if(a==='open-lead')return openLead(id);
  if(a==='claim'){await api('/leads/'+id+'/claim',{method:'POST'});toast('Inquiry assigned to you.');return openLead(id);}
  if(a==='activate'){await api('/leads/'+id+'/activate',{method:'POST'});toast('Moved into active sales. No messages sent.');return openLead(id);}
  if(a==='page-next'){S.offset+=30;return navigate('sales');}
  if(a==='page-prev'){S.offset=Math.max(0,S.offset-30);return navigate('sales');}
  if(a==='choose-quote')return chooseLead('quote');
  if(a==='choose-ai')return chooseLead('ai');
  if(a==='new-quote')return newQuote(id);
  if(a==='open-quote')return openQuote(id);
  if(a==='calculate-quote'){const d=quoteData();if(!d)return;const r=await api('/quotes/calculate',{method:'POST',data:d});S.modalContext.lastResult=r;document.getElementById('quote-result').innerHTML=quoteSummary(r);return;}
  if(a==='qbo-estimate'){const q=S.modalContext?.quote;if(!q)return;return showModal('Sync estimate to QuickBooks',`<div class="callout orange"><strong>Review before writing to accounting</strong>This creates a draft estimate in the connected QuickBooks environment. Nothing is emailed to the client.</div><div class="spacer"></div><form id="qbo-estimate-form" data-form="qbo-estimate"><input type="hidden" name="id" value="${h(id)}">${select('basis','Amount to send',[['low','Low end of estimate'],['high','High end of estimate']],'low','required')}</form>`,formFooter('qbo-estimate-form','Create QuickBooks estimate'));}
  if(a==='quote-text'){const t=await api('/quotes/'+id+'/draft-text');S.modalContext={...S.modalContext,draft:t};return showModal('Email draft',`<div class="callout orange">Not sent. Review the text and booking status before delivery.</div><div class="spacer"></div>${field('draft_subject','Subject',t.subject)}${textArea('draft_body','Message',t.body,15)}`,btn('copy-draft','Copy email text','btn-primary'));}
  if(a==='copy-draft')return copyText(document.getElementById('f-draft_body').value);
  if(a==='ai-compose')return aiCompose(id);
  if(a==='save-ai-reply'){const c=S.modalContext;await api('/leads/'+c.lead.id+'/messages',{method:'POST',data:{kind:'Draft reply',body:c.aiResult.draft_reply,subject:'AI-assisted draft'}});return toast('Draft saved to the client timeline. Not sent.');}
  if(a==='copy-ai-reply')return copyText(S.modalContext.aiResult.draft_reply);
  if(a==='review-ai-fields'){const c=S.modalContext;const fields=c.aiResult.fields;await editLead(c.lead.id);for(const [k,v]of Object.entries(fields)){const input=document.querySelector(`#lead-form [name="${k}"]`);if(input&&v!==null&&v!==''){input.value=v;input.style.borderColor='#dda451';}}document.getElementById('modal-error').innerHTML='AI suggestions are highlighted. Verify every change before saving; nothing has been applied yet.';return;}
  if(a==='week-prev'||a==='week-next'){weekDays();S.week.setDate(S.week.getDate()+(a==='week-next'?7:-7));return navigate('schedule');}
  if(a==='week-today'){S.week=null;return navigate('schedule');}
  if(a==='view-week'||a==='view-list'){S.scheduleView=a.slice(5);return navigate('schedule');}
  if(a==='new-job')return newJob(el.dataset);
  if(a==='open-imported-job')return openImportedJob(id);
  if(a==='open-job')return openJob(id);
  if(a==='job-status'){await api('/jobs/'+id,{method:'PATCH',data:{version:Number(el.dataset.version),status:el.dataset.status}});toast('Job status saved.');return openJob(id);}
  if(a==='cancel-job'){if(!confirm('Cancel this pilot job? It will remain in the history.'))return;await api('/jobs/'+id,{method:'PATCH',data:{version:Number(el.dataset.version),status:'Cancelled'}});modal.close();return navigate('schedule');}
  if(a==='confirm-job')return noteAction('Confirm this job','confirm-job',id,'All assigned resources, the accepted quote and verified deposit will be checked again. Any manual booking/deposit exception must already be documented on this job.');
  if(a==='tasks-active'||a==='tasks-imported'){S.taskScope=a==='tasks-active'?'active':'imported';return navigate('followups');}
  if(a==='complete-task'){await api('/tasks/'+id+'/complete',{method:'POST'});return navigate('followups');}
  if(a==='new-payment')return newPayment();
  if(a==='verify-payment'){if(!confirm('Have you verified that the funds were received?'))return;await api('/payments/'+id+'/verify',{method:'POST'});toast('Receipt verified.');return navigate('payments');}
  if(a==='qbo-payment'){if(!confirm('Post this verified, fully allocated receipt to the connected QuickBooks environment?'))return;const out=await api('/payments/'+id+'/quickbooks',{method:'POST',data:{confirm:true}});toast(out.duplicate?'Payment was already synchronized.':'QuickBooks payment synchronized.');return navigate('payments');}
  if(a==='reverse-payment')return noteAction('Reverse a payment entry','reverse-payment',id,'This creates an offsetting ledger entry. It does not issue a refund or delete the original payment.');
  if(a==='invite')return inviteForm();
  if(a==='disable-user'){if(!confirm('Revoke this user\'s access and active sessions?'))return;await api('/users/'+id+'/disable',{method:'POST'});return navigate('settings');}
  if(a==='driver-review')return noteAction('Verify driver authorization','driver-review',id,'Check licence, insurance eligibility, authorization and training for the actual vehicle. This is a manual verification record, not a licence lookup.');
  if(a==='add-time')return addTime(id);
  if(a==='approve-time'){await api('/times/'+id+'/approve',{method:'POST'});toast('Hours approved for review/export. No payroll payment made.');return navigate('team');}
  if(a==='stock-move')return showModal('Inventory movement',`<form id="stock-form" data-form="stock"><input type="hidden" name="id" value="${h(id)}"><h3>${h(el.dataset.name)}</h3><div class="grid2">${field('quantity','Quantity change (+ received / - used)','','number','step="1" required')}${field('reason','Reason / job reference','','text','required')}</div></form>`,formFooter('stock-form','Save movement'));
  if(a==='activate-vehicle')return noteAction('Verify this truck','activate-vehicle',id,'Confirm this is a real vehicle in your fleet and is available for the pilot. Record the truck identifier and any relevant capacity details.');
  if(a==='approve-pricing')return noteAction('Approve the source rate table','approve-pricing',id,'Review the seasonal rates. Approval does not choose between the overlapping fuel or minimum settings: each estimate must explicitly select its applicable rule. This pilot calculator is for local moves and excludes tax calculation.');
  if(a==='new-vehicle')return showModal('Add a truck',`<form id="vehicle-form" data-form="vehicle"><div class="grid2">${field('name','Truck identifier','','text','required')}${field('color_hex','Schedule color','#3B82F6','color','required')}${field('notes','Vehicle / availability notes')}</div><div class="spacer"></div><label class="checkbox-label"><input type="checkbox" name="active">Verified and available for pilot assignments</label></form>`,formFooter('vehicle-form','Save truck'));
  if(a==='import')return showModal('Import the CrownOps workbook',`<div class="callout orange"><strong>Private snapshot import, not a live sync</strong>Existing records are not overwritten. No emails or reminders will be sent. Incomplete schedule/payroll examples are quarantined.</div><div class="spacer"></div><form id="import-form" data-form="import"><div class="form-field"><label for="workbook-file">Original CrownOps v8 workbook (.xlsx)</label><input id="workbook-file" type="file" name="file" accept=".xlsx" required></div><div class="spacer"></div><p class="tiny muted">Your workbook remains unchanged. It is read into the protected server-side database. Importing the same file twice will not create duplicate records.</p></form>`,formFooter('import-form','Import snapshot','upload'));
  if(a==='history'){const hist=await api('/audit');return showModal('Change history',`<div class="stack">${hist.map(x=>`<div class="activity-row">${icon('clock')}<div><div class="small strong">${h(x.action)}</div><div class="tiny muted">${h(x.actor_name||x.actor)} &middot; ${h(x.created_at)} &middot; ${h(x.object_id)}</div></div></div>`).join('')||'<p class="muted">No events yet.</p>'}</div>`,btn('close','Close'));}
  if(a==='demo-export')return toast('Preview only. Run the server app to generate real exports.');
 }catch(error){modal.open?modalError(error):toast(error.message);}
});

document.addEventListener('submit',async e=>{
 const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form;const d=readForm(form);const submit=document.querySelector(`button[form="${form.id}"]`)||form.querySelector('button[type="submit"]');if(submit)submit.disabled=true;
 try{
  if(type==='setup-owner'){await api('/setup-owner',{method:'POST',data:d});const res=await api('/login',{method:'POST',data:{email:d.email,password:d.password,mfa_code:''}});S.user=res.user;S.csrf=res.csrf;shell();return navigate('dashboard');}
  if(type==='login'){const res=await api('/login',{method:'POST',data:d});S.user=res.user;S.csrf=res.csrf;shell();return navigate(S.user.role==='crew'?'schedule':'dashboard');}
  if(type==='accept-invite'){const out=await api('/accept-invitation',{method:'POST',data:d});location.hash='';loginScreen();toast('Account created. Sign in with '+out.email);return;}
  if(type==='lead'){const id=d.id;delete d.id;d.version=Number(d.version);const result=await api(id?'/leads/'+encodeURIComponent(id):'/leads',{method:id?'PATCH':'POST',data:d});toast(id?'Client details saved.':'Inquiry created with an internal follow-up task.');await navigate('sales');return openLead(id||result.id);}
  if(type==='note'){await api('/leads/'+d.lead_id+'/messages',{method:'POST',data:d});return openLead(d.lead_id);}
  if(type==='choose')return d.action==='ai'?aiCompose(d.lead_id):newQuote(d.lead_id);
  if(type==='quote'){const qd=quoteData();if(!qd)return;const q=await api('/quotes',{method:'POST',data:qd});toast('Draft revision saved. Nothing sent.');await navigate('quotes');return openQuote(q.id);}
  if(type==='qbo-estimate'){const out=await api('/quotes/'+d.id+'/quickbooks',{method:'POST',data:{confirm:true,basis:d.basis}});modal.close();toast(out.duplicate?'Estimate was already synchronized.':'QuickBooks estimate created.');return navigate('quotes');}
  if(type==='approve-quote'){await api('/quotes/'+d.id+'/approve',{method:'POST',data:{note:d.note,reviewed:form.reviewed.checked}});toast('Quote approved. Accounting request queued, not sent.');await navigate('quotes');return openQuote(d.id);}
  if(type==='accept-quote'){await api('/quotes/'+d.id+'/accept',{method:'POST',data:{reference:d.reference}});toast('Client acceptance recorded. Dispatch approval is still required.');await navigate('quotes');return openQuote(d.id);}
  if(type==='ai'){d.consent_to_process=form.consent_to_process.checked;d.request_id=window.crypto?.randomUUID?crypto.randomUUID():'req_'+Date.now()+'_'+Math.random().toString(36).slice(2);document.getElementById('ai-output').innerHTML='<div class="callout">Reviewing this message. No client information will be changed automatically...</div>';const out=await api('/ai/analyze',{method:'POST',data:d});S.modalContext.aiResult=out.result;const r=out.result;document.getElementById('ai-output').innerHTML=`<h3>Suggested summary</h3><p class="small muted">${h(r.summary)}</p><div class="review-list">${r.risk_flags.map(x=>`<span class="pill orange">${h(x)}</span>`).join('')}</div><div class="spacer"></div>${r.questions.length?'<h3>Questions to clarify</h3>'+r.questions.map(x=>`<p class="tiny muted">${h(x)}</p>`).join(''):''}<h3>Draft reply</h3><div class="message-draft">${h(r.draft_reply)}</div><div class="token-bar"><span>${demo()?'Sample output, not AI-generated':'Input: '+out.usage.input_tokens+' | Output: '+out.usage.output_tokens}</span><span>Not sent</span></div><div class="spacer"></div><div class="row wrap">${btn('review-ai-fields','Review suggested fields','btn-soft')}${btn('save-ai-reply','Save draft','btn-primary')}${btn('copy-ai-reply','Copy','btn-small')}</div>`;return;}
  if(type==='job'){d.crew_ids=checked(form,'crew_ids');d.truck_ids=checked(form,'truck_ids');d.stops=d.stops.split('\n').map(x=>x.trim()).filter(Boolean);d.capacity_reviewed=form.capacity_reviewed.checked;const j=await api('/jobs',{method:'POST',data:d});modal.close();toast('Pilot job saved. Live schedule unchanged.');await navigate('schedule');return openJob(j.id);}
  if(type.startsWith('invoice-'))return await invoiceSubmit(type,d,form);
  if(type==='payment'){d.amount=Number(d.amount);d.verified=Boolean(form.verified?.checked);await api('/payments',{method:'POST',data:d});modal.close();toast('Payment recorded. No charge or transfer initiated.');return navigate('payments');}
  if(type==='time'){d.service_hours=Number(d.service_hours);d.transport_hours=Number(d.transport_hours);await api('/times',{method:'POST',data:d});modal.close();toast('Time submitted for review.');return navigate('team');}
  if(type==='invite'){const out=await api('/invitations',{method:'POST',data:d});return showModal('Invitation created',`<div class="callout">Share this link privately with the intended employee. It expires in 48 hours and works once. No email was sent.</div><div class="spacer"></div>${textArea('draft_body','Private invitation link',out.url,3)}`,btn('copy-draft','Copy private link','btn-primary'));}
  if(type==='stock'){await api('/inventory/'+d.id+'/movement',{method:'POST',data:{quantity:Number(d.quantity),reason:d.reason}});modal.close();toast('Stock movement recorded.');return navigate('inventory');}
  if(type==='vehicle'){d.active=form.active.checked;await api('/vehicles',{method:'POST',data:d});modal.close();return navigate('settings');}
  if(type==='import'){if(demo()){toast('File import is available in the runnable server app, not this sample preview.');return;}const data=new FormData();data.append('file',form.file.files[0]);const report=await api('/imports/workbook',{method:'POST',form:data});await navigate('settings');return showModal(report.already_imported?'Already imported':'Import completed',`<div class="callout teal"><strong>${report.already_imported?'No duplicate records were created.':'Your source records are now in the private pilot database.'}</strong>No client messages, live bookings or payroll transactions were created.</div><div class="spacer"></div><div class="grid2">${Object.entries(report.counts).filter(([k,v])=>v>0||['Confirmed jobs imported','Payroll transactions imported'].includes(k)).map(([k,v])=>`<div><div class="info-label">${h(k)}</div><div class="strong">${v}</div></div>`).join('')}</div><div class="spacer"></div><p class="small muted">${report.quarantined.length} schedule row(s) quarantined. ${report.duplicate_records_skipped} existing records preserved.</p>`,btn('close','Continue','btn-primary'));}
  if(type==='action-note'){const c=S.modalContext.noteAction;const map={'approve-pricing':['/pricing/'+c.id+'/approve',{acknowledge:form.acknowledge.checked,note:d.note}],'activate-vehicle':['/vehicles/'+c.id+'/activate',{note:d.note}],'driver-review':['/employees/'+c.id+'/verify-driver',{note:d.note,verified:true}],'reverse-payment':['/payments/'+c.id+'/reverse',{note:d.note}],'confirm-job':['/jobs/'+c.id+'/confirm',{note:d.note,reviewed:form.acknowledge.checked,version:c.version}]};const [url,body]=map[c.action];await api(url,{method:'POST',data:body});modal.close();toast('Review saved.');return navigate(S.page);}
 }catch(error){if(type==='login'||type==='accept-invite'||type==='setup-owner'){document.getElementById('login-error').textContent=error.message;}else modalError(error);}finally{if(submit)submit.disabled=false;}
});
function setupScreen(){if(modal.open)modal.close();root.innerHTML=`<div class="login-screen"><div class="login-brand"><div class="brand" style="padding:0"><div class="brand-icon">${crown}</div><div><strong>CrownOps</strong><small>CROWN MOVERS</small></div></div><h1>Set up CrownOps.<br>Then you are in.</h1><p>Create the first Manager account for this private workspace.</p><div class="spacer"></div><div class="tiny" style="color:#92aed1">PRIVATE STAGING · EXTERNAL AUTOMATIONS OFF</div></div><div class="login-form"><div class="eyebrow">FIRST-TIME SETUP</div><div class="spacer"></div><h2>Create Manager account</h2><p class="small muted">Use the private setup code sent to the Crown Movers email account. This setup disappears after the first Manager is created.</p><form id="login-form" data-form="setup-owner">${field('setup_code','Private setup code','','password','autocomplete="one-time-code" required')}${field('name','Full name','','text','autocomplete="name" required')}${field('email','Email','','email','autocomplete="username" required')}${field('password','Create password','','password','minlength="12" autocomplete="new-password" required')}<button class="btn-primary" type="submit">Create Manager account ${icon('arrow')}</button><div id="login-error" class="login-error" role="alert"></div></form><p class="login-note">Use at least 12 characters. CrownOps will sign you in automatically after setup.</p></div></div>`;}
function loginScreen(){if(modal.open)modal.close();const invite=location.hash.startsWith('#invite=')?location.hash.slice(8):'';root.innerHTML=`<div class="login-screen"><div class="login-brand"><div class="brand" style="padding:0"><div class="brand-icon">${crown}</div><div><strong>CrownOps</strong><small>CROWN MOVERS</small></div></div><h1>Every client.<br>Every crew.<br>One workspace.</h1><p>Sales, estimates and scheduling, built around the way Crown Movers works.</p><div class="spacer"></div><div class="tiny" style="color:#92aed1">PRIVATE PILOT &middot; HUMAN-APPROVED AUTOMATION</div></div><div class="login-form"><div class="eyebrow">CROWN MOVERS WORKSPACE</div><div class="spacer"></div><h2>${invite?'Set up your account':'Welcome back'}</h2><p class="small muted">${invite?'Use your private invitation to create your own login.':'Sign in to your private operations workspace.'}</p><form id="login-form" data-form="${invite?'accept-invite':'login'}">${invite?`<input type="hidden" name="token" value="${h(invite)}">`:field('email','Email','','email','autocomplete="username" required')}${field('password','Password','','password','minlength="12" autocomplete="'+(invite?'new-password':'current-password')+'" required')}${invite?'':field('mfa_code','Authenticator code (when enabled)','','text','inputmode="numeric" autocomplete="one-time-code"')}<button class="btn-primary" type="submit">${invite?'Create account':'Sign in'} ${icon('arrow')}</button><div id="login-error" class="login-error" role="alert"></div></form><p class="login-note">${invite?'Already registered? Remove the invitation link and sign in.':'Use your CrownOps account. If this is the first online setup, reload the page.'}</p>${demo()?'<button id="demo-enter" class="btn-soft">Open fictional demo</button>':''}</div></div>`;if(demo())document.getElementById('demo-enter').onclick=bootstrap;}

// Final invoices are separate from quotations and employee payroll time.
async function invoicesPage(){const list=await api('/invoices');return head('Final invoices','Finish the job, enter actual hours and materials, then review the client invoice.')+`<div class="callout teal"><strong>Everyone on the assigned moving team can update the final invoice.</strong>Actual hours and approved material quantities are editable. Agreed rates, transport, tax settings and discounts stay locked. No money is collected or email sent in this pilot.</div><div class="spacer"></div><div class="panel">${list.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Invoice</th><th>Status</th><th>Total</th><th>Balance</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td class="client-name">${h(i.client_name)}</td><td>${h(i.number)}<div class="tiny muted">Revision ${i.revision}</div></td><td>${pill(i.status)}</td><td>${money(i.calculation.total_cents)}</td><td>${money(i.calculation.balance_cents)}</td><td>${btn('open-invoice','Open invoice','btn-primary btn-small',`data-id="${h(i.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('No job invoices yet',may(['owner'])?'Open a confirmed job in Schedule and approve its billing setup.':'Your manager must approve the job billing setup first. You will then be able to enter actuals.')}</div>`;}
function invoiceTotals(r){return `<div class="panel panel-body"><div class="info-grid"><div><div class="info-label">Service subtotal before discount</div>${money(r.lines.reduce((n,l)=>n+l.amount_cents,0))}</div><div><div class="info-label">Agreed discount</div>${money(r.discount_cents)}</div>${r.taxes.map(t=>`<div><div class="info-label">${h(t.name)} (${h(t.rate_percent)}%)</div>${money(t.amount_cents)}</div>`).join('')}<div><div class="info-label">Total</div><strong>${money(r.total_cents)}</strong></div><div><div class="info-label">Verified payments allocated</div>${money(r.deposit_cents)}</div><div><div class="info-label">Balance</div><strong>${money(r.balance_cents)}</strong></div></div></div>`;}
async function openInvoice(iid){const [i,conn]=await Promise.all([api('/invoices/'+iid),qboState()]);S.modalContext={invoice:i,qbo:conn};const t=i.terms,r=i.calculation;const draft=i.status==='Draft';const qboButton=!draft&&qboReady(conn)&&may(['owner','accounting'])?btn('qbo-invoice','Sync to '+qboLabel(conn),'btn-soft',`data-id="${h(i.id)}"`):'';showModal('Final invoice | '+h(i.client_name),`<div class="row">${pill(i.status)}<span class="tiny muted">${h(i.number)} | Revision ${i.revision}</span></div><div class="spacer"></div><div class="callout"><strong>Agreed prices are locked</strong>Team rate ${money(t.hourly_rate_cents)}/h. Service minimum ${t.minimum_hours} h. Transport ${money(t.transport_amount_cents)}. Fuel ${money(t.fuel_amount_cents)}. An employee's pay is not changed by this invoice.</div><div class="spacer"></div>${draft?`<form id="invoice-form" data-form="invoice-actuals"><input type="hidden" name="id" value="${h(i.id)}"><input type="hidden" name="version" value="${i.version}"><div class="grid2">${field('service_hours','Actual service hours',i.actual.service_hours??'','number','min="0" max="100" step="0.25" required')}${field('reason','Reason / what changed',i.actual.reason||'Actual hours and materials confirmed at end of service','text','required')}</div><div class="spacer"></div><h3>Materials / extras already approved for this job</h3><div class="grid2">${t.catalogue.map(c=>field('qty_'+c.code,c.name+' ('+money(c.unit_cents)+' each)',i.actual.quantities?.[c.code]||0,'number','min="0" max="10000" step="1"')).join('')||'<p class="small muted">None approved. Ask management before adding a new charge.</p>'}</div>${textArea('notes','Notes visible to the client',i.actual.notes||'',3)}<div class="spacer"></div><button class="btn-primary" type="submit">Save &amp; recalculate</button></form>`:`<p class="small">This revision has been issued in the pilot. Corrections create a new revision and keep the original.</p>`}<div class="spacer"></div>${invoiceTotals(r)}${!r.actual_hours_recorded?'<p class="source-warning">No actual hours entered yet. The displayed amount is not a final invoice.</p>':''}<div class="spacer"></div><div class="row wrap">${draft&&r.actual_hours_recorded&&i.job_status==='Completed'?btn('issue-invoice','Finalize invoice','btn-primary',`data-id="${h(i.id)}"`):''}${draft&&i.job_status!=='Completed'?'<p class="small muted">Mark the job Completed in Schedule before finalizing.</p>':''}${!draft?btn('download-invoice','Download client invoice','btn-primary',`data-id="${h(i.id)}"`)+btn('correct-invoice','Make a correction','',`data-id="${h(i.id)}"`):''}${qboButton}${may(['owner','accounting'])?btn('invoice-deposit','Apply verified deposit','',`data-id="${h(i.id)}"`):''}</div><p class="tiny muted">Download is a printable HTML document; your browser can print or save it as PDF. QuickBooks sync is available only when the reviewed accounting connection, mappings and write gate are enabled.</p>${i.history.length?'<p class="tiny muted">Preserved issued revisions: '+i.history.map(x=>'r'+x.revision).join(', ')+'</p>':''}`,btn('close','Close'),true);}
async function openJobInvoice(jid){const i=await api('/jobs/'+jid+'/invoice');if(i.ready===false){if(may(['owner']))return setupInvoice(jid);return showModal('Billing setup needed',`<div class="callout orange">${h(i.message)}</div>`,btn('close','Close'));}return openInvoice(i.id);}
async function setupInvoice(jid){const [jobs,quotes,stock]=await Promise.all([api('/jobs'),api('/quotes'),api('/inventory')]);const j=jobs.find(x=>x.id===jid);if(!j)throw Error('Job not found.');const q=quotes.find(x=>x.id===j.quote_id),r=q?.result||{};showModal('Manager: approve billing for '+h(j.title),`<p class="small">Review the accepted job terms with accounting before enabling team invoicing. Tax settings here are explicit inputs, not automatic legal advice.</p><form id="invoice-setup-form" data-form="invoice-setup"><input type="hidden" name="job_id" value="${h(jid)}"><div class="grid2">${field('issuer_name','Legal business name','Crown Movers','text','required')}${field('issuer_address','Business billing address','','text','required')}${field('issuer_email','Business email','info@crownmovers.ca','email','required')}${field('issuer_phone','Business phone','514-606-4030')}${field('customer_name','Bill to',j.client.client_name,'text','required')}${field('customer_address','Client billing address',j.client.dropoff)}${field('customer_email','Client email',j.client.email,'email')}${field('hourly_rate','Agreed team rate',r.hourly_rate_cents?r.hourly_rate_cents/100:'','number','step="0.01" min="1" required')}${field('minimum_hours','Agreed service minimum',r.minimum_hours??'','number','step="0.25" min="0" required')}${field('transport_amount','Agreed transport amount',r.transport_cents!==undefined?r.transport_cents/100:'','number','step="0.01" min="0" required')}${field('fuel_amount','Agreed fuel amount',r.fuel_cents!==undefined?r.fuel_cents/100:'','number','step="0.01" min="0" required')}${field('discount_amount','Agreed discount',r.discount_cents?r.discount_cents/100:0,'number','step="0.01" min="0" required')}</div>${textArea('taxes_json','Reviewed tax lines JSON: name, rate_percent, registration. Enter [] only when explicitly not applicable.','',4)}${textArea('catalogue_json','Approved material/extra prices (edit before approving)',JSON.stringify(stock.filter(x=>x.sell_cents>0).map(x=>({code:x.id,name:x.name,unit_price:x.sell_cents/100})),null,2),5)}${textArea('approval_reference','Accepted terms reference and review note','',3)}<label class="checkbox-label"><input type="checkbox" name="confirmed" required>I reviewed the accepted prices, tax treatment, and item prices. I authorize the assigned team to enter actuals and finalize this job invoice.</label></form>`,formFooter('invoice-setup-form','Approve billing setup'),true);}
async function invoiceClick(a,id){
 if(a==='open-invoice')return openInvoice(id);
 if(a==='job-invoice')return openJobInvoice(id);
 const i=S.modalContext?.invoice;
 if(a==='issue-invoice'){if(!confirm('I have reviewed the hours, materials and balance with the client. Finalize this test invoice?'))return;await api('/invoices/'+id+'/issue',{method:'POST',data:{version:i.version,confirmed:true}});toast('Test invoice finalized. No email or payment sent.');return openInvoice(id);}
 if(a==='correct-invoice'){const reason=prompt('Why does this invoice need correcting?');if(!reason)return;await api('/invoices/'+id+'/correct',{method:'POST',data:{version:i.version,reason}});return openInvoice(id);}
 if(a==='download-invoice'){
  let text;if(demo())text=await api('/invoices/'+id+'/document');else{const response=await fetch('/api/invoices/'+id+'/document');if(!response.ok)throw Error('Invoice document could not be downloaded.');text=await response.text();}
  const url=URL.createObjectURL(new Blob([text],{type:'text/html'})),link=document.createElement('a');link.href=url;link.download=(i?.number||id)+'-r'+i.revision+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('Invoice document downloaded. No email sent.');}
 if(a==='qbo-invoice'){if(!confirm('Sync this issued invoice to the connected QuickBooks environment? Review the total and mappings first.'))return;const out=await api('/invoices/'+id+'/quickbooks',{method:'POST',data:{confirm:true}});toast(out.already_synced?'Already synchronized with QuickBooks.':out.amount_matches?'QuickBooks invoice synchronized.':'QuickBooks total mismatch - review Connection activity.');return openInvoice(id);}
 if(a==='invoice-deposit'){const jobs=await api('/jobs'),j=jobs.find(x=>x.id===i.job_id);const p=(await api('/payments')).filter(x=>x.lead_id===j.lead_id&&x.verified&&x.amount_cents>0&&!x.reverses_id);return showModal('Apply an existing verified payment',`<form id="invoice-payment-form" data-form="invoice-payment"><input type="hidden" name="id" value="${h(id)}">${select('payment_id','Verified payment',p.map(x=>[x.id,x.reference+' | '+money(x.amount_cents)]))}${field('amount','Amount to apply','','number','min="0.01" step="0.01" required')}<p class="small muted">Payments cannot be reused across multiple invoices beyond their remaining unallocated amount.</p></form>`,formFooter('invoice-payment-form','Apply payment'));}
}
async function invoiceSubmit(type,d,form){
 if(type==='invoice-actuals'){const i=S.modalContext.invoice;const quantities=Object.fromEntries(i.terms.catalogue.map(c=>[c.code,Number(d['qty_'+c.code]||0)]));await api('/invoices/'+d.id,{method:'PATCH',data:{version:Number(d.version),service_hours:Number(d.service_hours),quantities,reason:d.reason,notes:d.notes}});return openInvoice(d.id);}
 if(type==='invoice-setup'){let taxes,catalogue;try{taxes=JSON.parse(d.taxes_json);catalogue=JSON.parse(d.catalogue_json);}catch{throw Error('Tax and material lists must contain valid JSON. Ask your developer/accountant for the reviewed setup.');}const out=await api('/jobs/'+d.job_id+'/invoice-setup',{method:'POST',data:{issuer:{name:d.issuer_name,address:d.issuer_address,email:d.issuer_email,phone:d.issuer_phone},customer:{name:d.customer_name,address:d.customer_address,email:d.customer_email},hourly_rate:Number(d.hourly_rate),minimum_hours:Number(d.minimum_hours),transport_amount:Number(d.transport_amount),fuel_amount:Number(d.fuel_amount),discount_amount:Number(d.discount_amount),taxes,catalogue,approval_reference:d.approval_reference}});return openInvoice(out.id);}
 if(type==='invoice-payment'){await api('/invoices/'+d.id+'/allocate-payment',{method:'POST',data:{payment_id:d.payment_id,amount:Number(d.amount)}});return openInvoice(d.id);}
}

document.addEventListener('change',async e=>{if(e.target.id==='demo-role'&&demo()){if(modal.open)modal.close();window.CROWNOPS_DEMO_SWITCH_ROLE(e.target.value);await bootstrap();}});
async function bootstrap(){try{if(location.hash.startsWith('#invite='))return loginScreen();if(!demo()){const health=await api('/health');if(health.setup_required)return setupScreen();}const out=await api('/me');S.user=out.user;S.csrf=out.csrf;shell();await navigate(may(['owner','sales'])?'dashboard':'schedule');}catch(e){loginScreen();}if(!demo()&&'serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
window.addEventListener('offline',()=>{const p=document.getElementById('pilot-strip');if(p){p.classList.add('offline');p.textContent='You are offline. Do not assume unsaved changes have been recorded.';}});
window.addEventListener('online',()=>toast('Connection restored. Refresh to load the current server records.'));

