document.addEventListener('change',e=>{if(e.target.id==='calendar-jump'&&e.target.value){const d=new Date(e.target.value+'T12:00:00');d.setDate(d.getDate()-d.getDay());S.week=d;S.scheduleView='week';navigate('schedule');}});
